int total = 0;
for (int batch = 1; batch <= 3; batch++)
{
    total += 4;
    Console.WriteLine($"Batch {batch}: {total}");
}

int total = 0;
while (true)
{
    string? input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input))
    {
        break;
    }
    if (!int.TryParse(input, out int quantity) || quantity < 1)
    {
        Console.WriteLine("Skipped");
        continue;
    }
    total += quantity;
}
Console.WriteLine($"Total: {total}");

Console.WriteLine(CanIssue(stock: 8, requested: 3));
Console.WriteLine(CanIssue(stock: 8, requested: 8));
Console.WriteLine(CanIssue(stock: 8, requested: 9));
Console.WriteLine(CanIssue(stock: 8, requested: 0));

static bool CanIssue(int stock, int requested)
{
    return requested > 0 && requested <= stock;
}

string[] initial = { "P-101", "P-102" };
List<string> skus = new List<string>(initial);
skus.Add("P-103");

Console.WriteLine($"Initial: {initial.Length}");
Console.WriteLine($"Current: {skus.Count}");
Console.WriteLine($"First: {skus[0]}");
foreach (string sku in skus)
{
    Console.WriteLine(sku);
}

var stock = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
stock.Add("P-101", 12);
stock.Add("P-102", 0);
Console.WriteLine(stock.TryAdd("p-101", 2));

string[] requests = { "p-101", "P-102", "P-999" };
foreach (string sku in requests)
{
    if (stock.TryGetValue(sku, out int quantity))
    {
        Console.WriteLine($"{sku}: {quantity}");
    }
    else
    {
        Console.WriteLine($"{sku}: unknown");
    }
}
